spec.query:
import "strings"

nombre = (e) => if e == "baseline" then "Sin EMS" else if e == "reglas" then "Reglas" else if e == "reglas_dr" then "Reglas + resp. demanda" else "Predictivo (MPC)"
orden = (e) => if e == "baseline" then 0 else if e == "reglas" then 1 else if e == "reglas_dr" then 2 else 3

from(bucket: "ems")
  |> range(start: 0)
  |> filter(fn: (r) => r._measurement == "kpi" and r.escenario =~ /^(baseline|reglas|reglas_dr|mpc)(_fv)?$/ and r._field == "energia_kwh")
  |> last()
  |> group()
  |> map(fn: (r) => {
      e = strings.trimSuffix(v: r.escenario, suffix: "_fv")
      return {o: orden(e: e), estrategia: nombre(e: e),
          variante: if strings.hasSuffix(v: r.escenario, suffix: "_fv") then "Con paneles solares" else "Sin paneles", _value: r._value / 1000.0}
  })
  |> pivot(rowKey: ["o", "estrategia"], columnKey: ["variante"], valueColumn: "_value")
  |> sort(columns: ["o"])
  |> drop(columns: ["o"])
